import {batchScenery} from './geometry.mjs';
import * as T from '../three.module.min.js';
import {coastAt,channelAt,CROCS,crocodileAt,RACE_POINTS,raceIntervals,SHORTCUT,ROCKS,JELLIES,EXTRA_BOOSTS} from './expedition.mjs';
const material=c=>new T.MeshStandardMaterial({color:c,roughness:.85});
function add(parent,geo,color,x=0,y=0,z=0){const m=new T.Mesh(geo,material(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function strip(parent,points,color,height){const shape=new T.Shape();shape.moveTo(points[0][0],-points[0][1]);for(const p of points.slice(1))shape.lineTo(p[0],-p[1]);shape.closePath();const geo=new T.ExtrudeGeometry(shape,{depth:height,bevelEnabled:false,steps:1});geo.rotateX(-Math.PI/2);return add(parent,geo,color,0,-.2,0);}
export function addCoastsAndRace(parent){const group=new T.Group();parent.add(group);for(const side of [-1,1]){const edge=[];for(let z=75;z>=-305;z-=5)edge.push([coastAt(z,side),z]);const outer=edge.map(([x,z])=>[x+side*25,z]).reverse();strip(group,[...edge,...outer],'#a0a073',2.8);strip(group,[...edge.map(([x,z])=>[x-side*1.2,z]),...edge.map(([x,z])=>[x+side*4,z]).reverse()],'#d7c7a2',.95);for(let i=0;i<22;i++){const z=65-i*17,x=coastAt(z,side)+side*(5+Math.sin(i)*2);const rock=add(group,new T.DodecahedronGeometry(2+Math.sin(i)*.5,0),'#799078',x,2,z);rock.scale.y=.7;}}
 // Low banks delineate a narrow race channel without enclosing the northern sea.
 for(let z=-12;z>-229;z-=2){const now=raceIntervals(z),next=raceIntervals(z-2);if(now.length!==next.length)continue;now.forEach((span,i)=>{for(const side of [0,1]){const direction=side?1:-1,a=span[side]+direction*.8,b=next[i][side]+direction*.8;strip(group,[[a,z],[b,z-2],[b+direction*1.4,z-2],[a+direction*1.4,z]],'#c0b795',.9);}});}
 const gates=[...RACE_POINTS.map((p,i)=>({...p,gate:i,width:5.9})),...SHORTCUT.slice(1,-1).map((p,i)=>({...p,gate:i+4,width:2.8})),...EXTRA_BOOSTS.map(p=>({...p,gate:-1,width:2.8}))].map(p=>{const g=new T.Group();g.position.set(p.x,.3,p.z);parent.add(g);const flags=[];for(const x of [-p.width,p.width]){add(g,new T.CylinderGeometry(.1,.13,3.5,7),'#e2d8b9',x,1.6,0);const f=add(g,new T.PlaneGeometry(.9,.65),p.width<4?'#ff9c47':p.gate===0?'#ff6233':'#8bc7aa',x+.45,3,0);f.material.side=T.DoubleSide;flags.push(f);}if(p.gate===0||p.gate===RACE_POINTS.length-1)add(g,new T.BoxGeometry(12,.5,.4),'#ff824c',0,3.6,0);return {g,p,flags};});
 const signCanvas=Object.assign(document.createElement('canvas'),{width:512,height:160}),ctx=signCanvas.getContext('2d');ctx.fillStyle='#082e49';ctx.fillRect(0,0,512,160);ctx.fillStyle='#ffb071';ctx.font='bold 44px sans-serif';ctx.textAlign='center';ctx.fillText('⚠ ATAJO / SHORTCUT →',256,92);const sign=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(signCanvas),depthTest:false}));sign.scale.set(12,3.75,1);sign.position.set(62,5,-78);parent.add(sign);
 ROCKS.forEach(p=>{const rock=add(parent,new T.DodecahedronGeometry(1.4,0),'#7c8985',p.x,.3,p.z);rock.scale.y=.7;});const jellyMeshes=JELLIES.map(p=>{const g=new T.Group();g.position.set(p.x,.12,p.z);parent.add(g);const cap=add(g,new T.SphereGeometry(.63,12,8),'#e8a1de',0,.08,0);cap.scale.y=.4;for(let i=0;i<5;i++){const tentacle=add(g,new T.CylinderGeometry(.03,.02,.8,5),'#c17fd0',Math.sin(i*1.25)*.4,-.45,Math.cos(i*1.25)*.4);}return g;});
 const crocs=[...CROCS,{x:69,z:-124,phase:3}].map((c,index)=>{const g=new T.Group();parent.add(g);const body=add(g,new T.SphereGeometry(.75,12,8),'#5d8261',0,.2,0);body.scale.set(1,.48,2);const head=add(g,new T.BoxGeometry(1.2,.35,1.55),'#6e9569',0,.25,1.7);const snout=add(g,new T.BoxGeometry(.8,.2,1.3),'#789b6a',0,.1,2.65);for(const x of [-.42,.42]){add(g,new T.SphereGeometry(.13,7,7),'#e9d990',x,.52,1.68);add(g,new T.SphereGeometry(.065,6,6),'#0b2c31',x,.54,1.78);}for(let i=0;i<7;i++){const spike=add(g,new T.ConeGeometry(.16,.25,4),'#3f6249',0,.58,-1+i*.35);}const tail=add(g,new T.ConeGeometry(.5,2.4,7),'#547557',0,.1,-2.2);tail.rotation.x=-Math.PI/2;g.rotation.y=Math.PI/2;return {g,c};});
 batchScenery(group);const extensions=new Map();
 return {extend(z){const center=Math.max(0,Math.floor((-z-305)/200)),needed=new Set();for(let n=Math.max(0,center-1);n<=center+1;n++){needed.add(n);if(extensions.has(n))continue;const land=new T.Group();parent.add(land);for(const side of [-1,1]){const edge=[];for(let depth=0;depth<=200;depth+=5){const at=-305-n*200-depth;edge.push([coastAt(at,side),at]);}strip(land,[...edge,...edge.map(([x,z])=>[x+side*25,z]).reverse()],'#a0a073',2.8);strip(land,[...edge.map(([x,z])=>[x-side*1.2,z]),...edge.map(([x,z])=>[x+side*4,z]).reverse()],'#d7c7a2',.95);}batchScenery(land);extensions.set(n,land);}for(const [n,land] of extensions){if(needed.has(n))continue;parent.remove(land);land.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});extensions.delete(n);}},update(time,boat){for(const {g,p,flags} of gates){const gust=boat&&Math.hypot(boat.x-p.x,boat.z-p.z)<8;flags.forEach((f,i)=>{f.rotation.y=Math.sin(time*(gust?18:3)+i)*(gust?.75:.15);});}for(const g of jellyMeshes){g.position.y=.12+Math.sin(time*2+g.position.x)*.15;}for(const {g,c} of crocs){const p=crocodileAt(c,time);g.position.set(p.x,.05+Math.sin(time*2+c.phase)*.035,p.z);g.rotation.y=Math.PI/2+Math.sin(time*.8+c.phase)*.2;}}};}
export function addWorldBottle(parent,b){const g=new T.Group();g.position.set(b.x,.2,b.z);parent.add(g);const glass=new T.MeshStandardMaterial({color:'#78c9aa',roughness:.3,metalness:.08,transparent:true,opacity:.85});const body=new T.Mesh(new T.CylinderGeometry(.23,.23,.7,10),glass);g.add(body);body.rotation.z=1;const neck=new T.Mesh(new T.CylinderGeometry(.09,.16,.25,8),glass);neck.position.set(-.37,.23,0);neck.rotation.z=1;g.add(neck);const paper=add(g,new T.CylinderGeometry(.12,.12,.44,7),'#ffedc3');paper.rotation.z=1;const buoy=new T.Mesh(new T.TorusGeometry(.65,.02,4,24),new T.MeshBasicMaterial({color:'#e3f8c6',transparent:true,opacity:.7}));buoy.rotation.x=-Math.PI/2;buoy.position.y=-.1;g.add(buoy);g.scale.setScalar(1.6);return g;}
